"""Heat diffusion on a grid, with the stencil computed by a GPU compute shader (wgpu)."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = f"""
struct Dims {{
    width: u32,
    height: u32,
}};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size({WORKGROUP}, {WORKGROUP})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let x = gid.x;
    let y = gid.y;
    let w = dims.width;
    let h = dims.height;
    if (x >= w || y >= h) {{
        return;
    }}
    let xl = select(x - 1u, x, x == 0u);
    let xr = min(x + 1u, w - 1u);
    let yu = select(y - 1u, y, y == 0u);
    let yd = min(y + 1u, h - 1u);
    let row = y * w;
    let c = src[row + x];
    let total = 4u * c + src[row + xl] + src[row + xr] + src[yu * w + x] + src[yd * w + x];
    dst[row + x] = total / 8u;
}}
"""


def parse(path):
    with open(path) as f:
        tokens = f.read().split()
    if len(tokens) < 3:
        raise ValueError("input must start with <width> <height> <steps>")
    width, height, steps = (int(t) for t in tokens[:3])
    if not (1 <= width <= 512 and 1 <= height <= 512):
        raise ValueError("width and height must be between 1 and 512")
    if not (0 <= steps <= 1000):
        raise ValueError("steps must be between 0 and 1000")
    cells = tokens[3:]
    if len(cells) != width * height:
        raise ValueError(f"expected {width * height} cells, found {len(cells)}")
    grid = np.array([int(t) for t in cells], dtype=np.int64)
    if grid.size and (grid.min() < 0 or grid.max() > 1_000_000):
        raise ValueError("cells must be between 0 and 1000000")
    return width, height, steps, grid.astype(np.uint32)


def diffuse(width, height, steps, grid):
    if steps == 0:
        return grid.copy()

    device = wgpu.utils.get_default_device()
    shader = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": shader, "entry_point": "main"}
    )

    usage = (
        wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST
    )
    buffers = [
        device.create_buffer_with_data(data=grid.tobytes(), usage=usage),
        device.create_buffer(size=grid.nbytes, usage=usage),
    ]
    dims = device.create_buffer_with_data(
        data=np.array([width, height], dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    layout = pipeline.get_bind_group_layout(0)
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": dims}},
                {"binding": 1, "resource": {"buffer": buffers[i]}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i]}},
            ],
        )
        for i in (0, 1)
    ]

    groups_x = (width + WORKGROUP - 1) // WORKGROUP
    groups_y = (height + WORKGROUP - 1) // WORKGROUP
    encoder = device.create_command_encoder()
    for step in range(steps):
        # Separate passes so each step sees the previous step's completed writes.
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_groups[step % 2])
        compute.dispatch_workgroups(groups_x, groups_y, 1)
        compute.end()
    device.queue.submit([encoder.finish()])

    result = buffers[steps % 2]
    data = device.queue.read_buffer(result)
    return np.frombuffer(data, dtype=np.uint32).copy()


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    width, height, steps, grid = parse(argv[1])
    out = diffuse(width, height, steps, grid).reshape(height, width)
    lines = [" ".join(str(int(v)) for v in row) for row in out]
    lines.append(f"SUM {int(out.astype(np.int64).sum())}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

